solution.referenceSolution:
from typing import List

def min_largest_batch(loads: List[int], m: int) -> int:
    def pieces(cap):
        count, cur = 1, 0
        for x in loads:
            if cur + x > cap:
                count += 1
                cur = x
            else:
                cur += x
        return count
    lo, hi = max(loads), sum(loads)
    while lo < hi:
        mid = (lo + hi) // 2
        if pieces(mid) <= m:
            hi = mid
        else:
            lo = mid + 1
    return lo
